mapper.select:
select id, doc_id, protocol, version, frame_or_action, heading, content, locator, keywords
from ipe_ops.protocol_doc_section
where protocol = #{protocol}
  and version = #{version}
  and lower(frame_or_action) = lower(#{frameOrAction})
order by id

select id, doc_id, protocol, version, frame_or_action, heading, content, locator, keywords
from ipe_ops.protocol_doc_section
where protocol = #{protocol}
  and version = #{version}
  and (
      lower(content) like lower(concat('%', #{keyword}, '%'))
      or lower(keywords) like lower(concat('%', #{keyword}, '%'))
      or lower(heading) like lower(concat('%', #{keyword}, '%'))
  )
order by id
